import json, csv
with open('json/event.json') as f: events = {r['event_id']: r['event_name'] for r in json.load(f)['records']}
with open('json/expense.json') as f: expenses = json.load(f)['records']
with open('csv/budget.csv') as f: budgets = list(csv.DictReader(f))
budget_to_event = {b['budget_id']: b['link_to_event'] for b in budgets}
costs = {}
for e in expenses:
  bid = e.get('link_to_budget')
  eid = budget_to_event.get(bid)
  if eid and eid in events:
    costs[eid] = costs.get(eid, 0) + float(e['cost'])
min_cost = min(costs.values())
min_events = [events[eid] for eid in costs if costs[eid] == min_cost]
print('Min cost:', min_cost)
print('Event(s):', min_events)
